        { "FILETRACKER\n\n\u2022 File g\u1ea7n \u0111\u00e2y: th\u1eddi gian t\u1ea1o/s\u1eeda do Windows ghi nh\u1eadn; kh\u00f4ng kh\u1eb3ng \u0111\u1ecbnh \u0111\u00e2y l\u00e0 l\u00fac t\u1ea3i file.\n\u2022 L\u1ecbch s\u1eed thay \u0111\u1ed5i: Th\u00eam, S\u1eeda, X\u00f3a, \u0110\u1ed5i t\u00ean khi app ch\u1ea1y. Nh\u00e3n 'Ph\u00e1t hi\u1ec7n' l\u00e0 k\u1ebft qu\u1ea3 so s\u00e1nh khi qu\u00e9t l\u1ea1i, kh\u00f4ng bi\u1ebft ch\u00ednh x\u00e1c l\u00fac thao t\u00e1c x\u1ea3y ra.\n\u2022 Kh\u00f4ng kh\u00f4i ph\u1ee5c n\u1ed9i dung ho\u1eb7c phi\u00ean b\u1ea3n file c\u0169.\n\u2022 \u0110\u1ed5i t\u00ean th\u01b0 m\u1ee5c \u0111\u01b0\u1ee3c \u0111\u1ed1i so\u00e1t th\u00e0nh c\u00e1c file m\u1ea5t/th\u00eam; chuy\u1ec3n gi\u1eefa hai th\u01b0 m\u1ee5c theo d\u00f5i c\u00f3 th\u1ec3 hi\u1ec7n l\u00e0 X\u00f3a v\u00e0 Th\u00eam.\n\u2022 \u1ea8n file k\u1ef9 thu\u1eadt ch\u1ec9 l\u1ecdc giao di\u1ec7n. B\u1ecf qua th\u01b0 m\u1ee5c l\u1eadp tr\u00ecnh l\u00e0 c\u00e0i \u0111\u1eb7t ph\u1ea1m vi qu\u00e9t.\n\u2022 B\u1ecf qua junction/symlink, th\u00f9ng r\u00e1c v\u00e0 th\u01b0 m\u1ee5c h\u1ec7 th\u1ed1ng kh\u00f4ng \u0111\u1ecdc \u0111\u01b0\u1ee3c. Kh\u00f4ng c\u1ea7n quy\u1ec1n Administrator.\n\u2022 Gi\u1eef t\u1ed1i \u0111a 100.000 s\u1ef1 ki\u1ec7n g\u1ea7n nh\u1ea5t; m\u1ed7i trang 200 m\u1ee5c.\n\u2022 App kh\u00f4ng ghi nh\u1eadn l\u00fac \u0111\u00e3 tho\u00e1t/t\u1ea1m d\u1eebng. Qu\u00e9t l\u1ea1i kh\u00f4ng th\u1ec3 t\u00ecm file \u0111\u00e3 t\u1ea1o r\u1ed3i x\u00f3a trong th\u1eddi gian \u0111\u00f3.\n\u2022 Database ch\u1ec9 ch\u1ee9a t\u00ean, \u0111\u01b0\u1eddng d\u1eabn v\u00e0 th\u00f4ng tin file, \u1edf:\n", "FILETRACKER\n\n\u2022 Recent files: Windows creation/modification timestamps are not necessarily download times.\n\u2022 Activity history: live additions, modifications, deletions and renames. \u201cDetected\u201d events come from rescans; their exact original time is unknown.\n\u2022 Previous file contents and deleted files cannot be restored.\n\u2022 Folder renames are reconciled as missing/added files. Moving between monitored roots may appear as Deleted and Added.\n\u2022 Hide technical files only filters the view. Skipping development folders changes scan scope.\n\u2022 Directory junctions/symlinks, the recycle bin and unreadable system folders are skipped. Administrator access is not required.\n\u2022 Keeps up to 100,000 recent events after resync; 200 items per page.\n\u2022 No live recording while exited or paused. Rescanning cannot recover a file created and deleted during that gap.\n\u2022 The database stores only names, paths and file metadata at:\n" },
    };
    public static string T(string key) { string value; return Language=="en"&&English.TryGetValue(key,out value)?value:key; }
